// NOR gate module
module NOR (
    input  a,
    input  b,
    output out
);

reg res;

always @(posedge a or posedge b) begin
    if(a == 1'b1 && b == 1'b1) begin
        res = 1'b1;
    end else begin
        res = 1'b0;
    end
end

assign out = ~res;

endmodule

